CREATE TABLE `trips` (`id` text PRIMARY KEY NOT NULL, `destination` text, `start_date` text, `end_date` text, `travelers` integer DEFAULT 2 NOT NULL, `interests_json` text DEFAULT '[]' NOT NULL, `budget_limit` integer, `focused_destination_id` text, `version` integer DEFAULT 1 NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL);
CREATE TABLE `trip_candidates` (`trip_id` text NOT NULL REFERENCES `trips`(`id`) ON DELETE cascade, `destination_id` text NOT NULL, `source` text NOT NULL, `position` integer NOT NULL, PRIMARY KEY(`trip_id`,`destination_id`));
CREATE TABLE `itinerary_items` (`id` text PRIMARY KEY NOT NULL, `trip_id` text NOT NULL REFERENCES `trips`(`id`) ON DELETE cascade, `day` integer NOT NULL, `position` integer NOT NULL, `time` text NOT NULL, `title` text NOT NULL, `location` text NOT NULL, `note` text NOT NULL, `estimated_cost` integer NOT NULL, `source` text NOT NULL);
CREATE TABLE `trip_budgets` (`trip_id` text PRIMARY KEY NOT NULL REFERENCES `trips`(`id`) ON DELETE cascade, `transport` integer DEFAULT 0 NOT NULL, `stay` integer DEFAULT 0 NOT NULL, `food` integer DEFAULT 0 NOT NULL, `activities` integer DEFAULT 0 NOT NULL);
CREATE TABLE `chat_messages` (`id` text PRIMARY KEY NOT NULL, `trip_id` text NOT NULL REFERENCES `trips`(`id`) ON DELETE cascade, `role` text NOT NULL, `content` text NOT NULL, `status` text NOT NULL, `sequence` integer NOT NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL);
CREATE UNIQUE INDEX `chat_sequence` ON `chat_messages` (`trip_id`,`sequence`);
CREATE TABLE `tool_activities` (`id` text PRIMARY KEY NOT NULL, `trip_id` text NOT NULL REFERENCES `trips`(`id`) ON DELETE cascade, `message_id` text NOT NULL REFERENCES `chat_messages`(`id`) ON DELETE cascade, `tool_name` text NOT NULL, `label` text NOT NULL, `status` text NOT NULL, `sequence` integer NOT NULL, `created_at` text NOT NULL, `completed_at` text);
